patch -p0 <<'PATCH'
*** /dev/null
--- tests/unit/cluster/cluster-shards.tcl
***************
*** 0 ****
--- 1,62 ----
+ start_cluster 1 1 {tags {external:skip cluster}} {
+     test "CLUSTER SHARDS reports slots before failover" {
+         set primary_id [R 0 CLUSTER MYID]
+         set replica_id [R 1 CLUSTER MYID]
+         wait_for_sync [srv -1 client]
+ 
+         foreach id {0 1} {
+             set shards [R $id CLUSTER SHARDS]
+             assert_equal 1 [llength $shards]
+             assert_equal {0 16383} [dict get [lindex $shards 0] slots]
+             assert_equal 2 [llength [dict get [lindex $shards 0] nodes]]
+         }
+ 
+         # Keep the former primary first in the shard to exercise stale primary selection.
+         assert_equal $primary_id [dict get [lindex [dict get [lindex [R 1 CLUSTER SHARDS] 0] nodes] 0] id]
+     }
+ 
+     test "CLUSTER SHARDS reports slots after takeover with the former primary offline" {
+         set primary_pid [srv 0 pid]
+         pause_process $primary_pid
+ 
+         R 1 CLUSTER FAILOVER TAKEOVER
+         assert_equal master [s -1 role]
+         set shard [lindex [R 1 CLUSTER SHARDS] 0]
+         set nodes [dict get $shard nodes]
+         assert_equal 2 [llength $nodes]
+         assert_equal $primary_id [dict get [lindex $nodes 0] id]
+         foreach node $nodes {
+             assert_equal master [dict get $node role]
+         }
+ 
+         # Read repeatedly to also exercise cleanup of the generated slot ranges.
+         for {set i 0} {$i < 3} {incr i} {
+             assert_equal {0 16383} [dict get [lindex [R 1 CLUSTER SHARDS] 0] slots]
+         }
+ 
+         resume_process $primary_pid
+     }
+ 
+     test "CLUSTER SHARDS reports slots after the former primary rejoins" {
+         wait_for_condition 1000 50 {
+             [s 0 role] eq {slave}
+         } else {
+             fail "Former primary was not converted into a replica"
+         }
+         wait_for_cluster_propagation
+ 
+         foreach id {0 1} {
+             assert_equal {0 16383} [dict get [lindex [R $id CLUSTER SHARDS] 0] slots]
+         }
+     }
+ }
+ 
+ start_cluster 1 0 {tags {external:skip cluster}} {
+     test "CLUSTER SHARDS reports empty slots for a shard that owns no slots" {
+         R 0 CLUSTER FLUSHSLOTS
+         set shards [R 0 CLUSTER SHARDS]
+         assert_equal 1 [llength $shards]
+         assert_equal {} [dict get [lindex $shards 0] slots]
+         assert_equal 1 [llength [dict get [lindex $shards 0] nodes]]
+     }
+ }
PATCH
./runtest --single unit/cluster/cluster-shards

